export function fittedScale({width,height,viewportWidth,viewportHeight,paddingX=0,paddingY=0,chromeHeight=0,mode='page',safe=24}){const x=Math.max(1,viewportWidth-paddingX-safe)/width,y=Math.max(1,viewportHeight-paddingY-chromeHeight-safe)/height;return Math.max(.005,mode==='width'?x:Math.min(x,y));}
export function cameraPoint(viewport,canvas,scale){const v=viewport.getBoundingClientRect(),c=canvas.getBoundingClientRect();return {x:(v.left+viewport.clientWidth/2-c.left)/scale,y:(v.top+viewport.clientHeight/2-c.top)/scale};}
export function restoreCamera(viewport,canvas,scale,point){const v=viewport.getBoundingClientRect(),c=canvas.getBoundingClientRect();viewport.scrollLeft+=c.left+point.x*scale-v.left-viewport.clientWidth/2;viewport.scrollTop+=c.top+point.y*scale-v.top-viewport.clientHeight/2;}
